@import "tailwindcss";

/* Porsche Design System Integration Styles */
body {
  font-family: inherit; /* Let Porsche Design System handle typography */
  background-color: rgb(17, 24, 39); /* gray-900 */
  color: white;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* Porsche Design System Dark Theme Overrides */
p-text {
  color: rgb(209, 213, 219) !important; /* gray-300 - good contrast */
}

p-heading {
  color: rgb(96, 165, 250) !important; /* blue-400 - good contrast */
}

p-link {
  color: rgb(156, 163, 175) !important; /* gray-400 */
}

p-link:hover {
  color: white !important;
}

p-link[variant="secondary"] {
  color: rgb(156, 163, 175) !important; /* gray-400 */
}

p-link[variant="primary"] {
  color: rgb(59, 130, 246) !important; /* blue-500 */
}

p-button {
  color: white !important;
  background-color: rgb(59, 130, 246) !important; /* blue-500 */
}

p-button:hover {
  background-color: rgb(37, 99, 235) !important; /* blue-600 */
}

p-tag {
  color: rgb(17, 24, 39) !important; /* gray-900 for light background tags */
  background-color: rgb(209, 213, 219) !important; /* gray-300 */
}

p-tag[variant="neutral"] {
  color: rgb(17, 24, 39) !important; /* gray-900 */
  background-color: rgb(209, 213, 219) !important; /* gray-300 */
}

/* Wordmark styling */
p-wordmark {
  filter: brightness(0) invert(1); /* Make wordmark white on dark background */
}

/* Ensure all text has proper contrast */
.text-gray-300 {
  color: rgb(209, 213, 219) !important;
}

.text-gray-400 {
  color: rgb(156, 163, 175) !important;
}

.text-blue-400 {
  color: rgb(96, 165, 250) !important;
}

.text-red-400 {
  color: rgb(248, 113, 113) !important;
}

/* High contrast mode support */
@media (prefers-contrast: high) {
  p-text {
    color: white !important;
  }

  p-link {
    color: rgb(96, 165, 250) !important; /* blue-400 */
  }

  .text-gray-300 {
    color: white !important;
  }

  .text-gray-400 {
    color: rgb(209, 213, 219) !important; /* gray-300 */
  }
}

